import api from '../services/api';
import AppLayout from './AppLayout.vue';
import Toast from 'primevue/toast';
export default {
  name: 'ArchivePage',
  components: {
    AppLayout,
    Toast
  },
  data() {
    return {
      archivedFiles: [],
      selectedFiles: [],
      restoring: null,
      deleting: null,
      deleteDialog: false,
      fileToDelete: null,
      isBulkDelete: false,
      // Pagination
      currentPage: 1,
      itemsPerPage: 10,
      // Sorting
      sortColumn: 'archived_at',
      sortDirection: 'desc'
    };
  },
  computed: {
    isAllSelected() {
      return this.paginatedFiles.length > 0 && this.paginatedFiles.every(file => this.selectedFiles.includes(file.id));
    },
    sortedFiles() {
      const files = [...this.archivedFiles];
      files.sort((a, b) => {
        let aVal = a[this.sortColumn];
        let bVal = b[this.sortColumn];

        // Handle null/undefined values
        if (aVal === null || aVal === undefined) aVal = '';
        if (bVal === null || bVal === undefined) bVal = '';

        // Convert to lowercase for string comparison
        if (typeof aVal === 'string') aVal = aVal.toLowerCase();
        if (typeof bVal === 'string') bVal = bVal.toLowerCase();

        // Compare values
        if (aVal < bVal) return this.sortDirection === 'asc' ? -1 : 1;
        if (aVal > bVal) return this.sortDirection === 'asc' ? 1 : -1;
        return 0;
      });
      return files;
    },
    paginatedFiles() {
      const start = (this.currentPage - 1) * this.itemsPerPage;
      const end = start + this.itemsPerPage;
      return this.sortedFiles.slice(start, end);
    },
    totalFiles() {
      return this.archivedFiles.length;
    },
    totalPages() {
      return Math.ceil(this.totalFiles / this.itemsPerPage);
    },
    startIndex() {
      return (this.currentPage - 1) * this.itemsPerPage;
    },
    endIndex() {
      const end = this.startIndex + this.itemsPerPage;
      return end > this.totalFiles ? this.totalFiles : end;
    },
    visiblePages() {
      const pages = [];
      const maxVisible = 5;
      let start = Math.max(1, this.currentPage - Math.floor(maxVisible / 2));
      let end = Math.min(this.totalPages, start + maxVisible - 1);
      if (end - start < maxVisible - 1) {
        start = Math.max(1, end - maxVisible + 1);
      }
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    }
  },
  mounted() {
    this.loadArchivedFiles();
  },
  methods: {
    async loadArchivedFiles() {
      try {
        const response = await api.getArchivedFiles();
        this.archivedFiles = response.data.results || response.data;
        // Clear selection when reloading
        this.selectedFiles = [];
      } catch (error) {
        console.error('Error loading archived files:', error);
        this.$toast.error('Failed to load archived files');
      }
    },
    toggleSelect(fileId) {
      const index = this.selectedFiles.indexOf(fileId);
      if (index > -1) {
        this.selectedFiles.splice(index, 1);
      } else {
        this.selectedFiles.push(fileId);
      }
    },
    toggleSelectAll(event) {
      if (event.target.checked) {
        // Select all files on current page
        this.paginatedFiles.forEach(file => {
          if (!this.selectedFiles.includes(file.id)) {
            this.selectedFiles.push(file.id);
          }
        });
      } else {
        // Deselect all files on current page
        this.paginatedFiles.forEach(file => {
          const index = this.selectedFiles.indexOf(file.id);
          if (index > -1) {
            this.selectedFiles.splice(index, 1);
          }
        });
      }
    },
    isSelected(fileId) {
      return this.selectedFiles.includes(fileId);
    },
    clearSelection() {
      this.selectedFiles = [];
    },
    bulkDelete() {
      if (this.selectedFiles.length === 0) {
        this.$toast.warning('Please select files to delete');
        return;
      }
      this.isBulkDelete = true;
      this.deleteDialog = true;
    },
    async executeBulkDelete() {
      if (this.selectedFiles.length === 0) return;
      this.deleting = 'bulk';
      let successCount = 0;
      let failCount = 0;
      try {
        // Delete files one by one
        for (const fileId of this.selectedFiles) {
          try {
            await api.deleteUploadedFile(fileId);
            successCount++;
          } catch (error) {
            console.error(`Failed to delete file ${fileId}:`, error);
            failCount++;
          }
        }

        // Show result
        if (successCount > 0) {
          this.$toast.success(`Successfully deleted ${successCount} file(s)`);
        }
        if (failCount > 0) {
          this.$toast.error(`Failed to delete ${failCount} file(s)`);
        }
        this.deleteDialog = false;
        this.isBulkDelete = false;
        this.selectedFiles = [];
        this.loadArchivedFiles();
      } catch (error) {
        this.$toast.error('Failed to delete files');
      } finally {
        this.deleting = null;
      }
    },
    async restoreFile(file) {
      this.restoring = file.id;
      try {
        await api.restoreArchivedFile(file.id);
        this.$toast.success('File restored successfully!');
        this.loadArchivedFiles();
      } catch (error) {
        const errorMsg = error.response?.data?.error || 'Failed to restore file';
        this.$toast.error(errorMsg);
      } finally {
        this.restoring = null;
      }
    },
    confirmDelete(file) {
      this.fileToDelete = file;
      this.isBulkDelete = false;
      this.deleteDialog = true;
    },
    async deleteFile() {
      if (!this.fileToDelete) return;
      this.deleting = this.fileToDelete.id;
      try {
        const response = await api.deleteUploadedFile(this.fileToDelete.id);
        this.$toast.success(`File deleted permanently. ${response.data.reports_deleted || 0} records removed.`);
        this.deleteDialog = false;
        this.fileToDelete = null;
        this.loadArchivedFiles();
      } catch (error) {
        const errorMsg = error.response?.data?.error || 'Failed to delete file';
        this.$toast.error(errorMsg);
      } finally {
        this.deleting = null;
      }
    },
    formatDate(dateString) {
      return new Date(dateString).toLocaleString();
    },
    getStatusClass(status) {
      const statusMap = {
        'COMPLETED': 'success',
        'FAILED': 'error',
        'PROCESSING': 'warning',
        'PENDING': 'info'
      };
      return statusMap[status] || 'info';
    },
    // Pagination methods
    goToPage(page) {
      if (page >= 1 && page <= this.totalPages) {
        this.currentPage = page;
      }
    },
    nextPage() {
      if (this.currentPage < this.totalPages) {
        this.currentPage++;
      }
    },
    previousPage() {
      if (this.currentPage > 1) {
        this.currentPage--;
      }
    },
    changeItemsPerPage() {
      this.currentPage = 1; // Reset to first page when changing items per page
    },
    // Sorting methods
    sortBy(column) {
      if (this.sortColumn === column) {
        // Toggle direction if same column
        this.sortDirection = this.sortDirection === 'asc' ? 'desc' : 'asc';
      } else {
        // New column, default to ascending
        this.sortColumn = column;
        this.sortDirection = 'asc';
      }
    },
    getSortIcon(column) {
      if (this.sortColumn !== column) {
        return 'pi pi-sort-alt sort-icon';
      }
      return this.sortDirection === 'asc' ? 'pi pi-sort-amount-up-alt sort-icon active' : 'pi pi-sort-amount-down sort-icon active';
    }
  }
};
